<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {useStudio} from './studioContext'
import AppIcon from './AppIcon.vue'
import ReviewUnit from './ReviewUnit.vue'
const s=useStudio(),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(''),page=ref(1),checked=ref<string[]>([]),ranges=ref<Record<string,string>>({}),target=ref(''),personIds=ref<string[]>([]),summaryKinds=ref<string[]>(['background','relationships','narrative']),updateIds=ref<string[]>([]),query=ref(''),ocrRanges=ref<Record<string,string>>({})
const editing=ref(s.p.value.authoringDrafts?.candidate?.editing||''),editValues=ref<Record<string,string>>(s.p.value.authoringDrafts?.candidate?.values||{}),editError=ref('')
watch([editing,editValues],()=>{s.p.value.authoringDrafts||={};s.p.value.authoringDrafts.candidate={editing:editing.value,values:editValues.value}},{deep:true})
const inputMode=ref('file')
const textInput=computed(()=>s.rec('material','main').draft.literatureInput||{documentId:'',sourceVersion:0,title:'',citation:'',text:''})
const legacyText=computed(()=>Object.entries(labels).filter(([k])=>s.p.value.materialInputs?.[k]?.trim()).map(([k,label])=>label+'\n'+s.p.value.materialInputs[k]).join('\n\n'))
function editText(key:string,value:any){s.rec('material','main').draft.literatureInput={...textInput.value,[key]:value}}
function newText(){s.rec('material','main').draft.literatureInput={documentId:'',sourceVersion:0,title:'',citation:'',text:''}}
function copyLegacy(){const old=textInput.value.text;newText();editText('title','已有资料文本');editText('text',old&&old!==legacyText.value?old+'\n\n'+legacyText.value:legacyText.value);inputMode.value='text';notice.value='已复制到文本输入，原资料和现有文字保留；保存或整理后进入同一文献流程'}
function editDocument(d:any){const raw=s.p.value.sources.find((v:any)=>v.documentId===d.id&&v.page===1);s.rec('material','main').draft.literatureInput={documentId:d.id,sourceVersion:raw?.version||0,title:d.title,citation:d.citation||'',text:raw?.text||''};inputMode.value='text'}
async function importText(){
 if(!textInput.value.text.trim())throw Error('请输入文献原文')
 await s.saveAll();const result=await request(`/projects/${s.p.value.id}/documents/text`,'POST',{version:s.p.value.version,...textInput.value})
 await s.legacy(result.project);editText('documentId',result.documentId);editText('sourceVersion',result.sourceVersion)
 selected.value=result.documentId;checked.value=Array.from(new Set([...checked.value,result.documentId]));page.value=1
}
async function saveText(){await run(async()=>{await importText();notice.value='文本已保存为文献原文，未调用模型；勾选后使用下方统一整理入口'})}
const editFields=[{key:'name',label:'姓名或称谓',max:100,rows:1},{key:'identity',label:'身份',max:1000,rows:1},{key:'summary',label:'简介',max:4000,rows:4},{key:'biography',label:'经历',max:8000,rows:3},{key:'relationships',label:'人物关系',max:4000,rows:3}]
const labels:Record<string,string>={background:'历史背景',relationships:'人物与关系',narrative:'已有历史叙事'},roles:Record<string,string>={depicted:'本画人物',historical_background:'历史背景',creator:'作者',inscriber:'题跋',collector:'收藏流传',scholar:'研究者',other_artwork:'其他作品',uncertain:'范围未定'}
const docs=computed(()=>s.p.value.documents||[]),doc=computed(()=>docs.value.find((d:any)=>d.id===selected.value)||docs.value[0]),analysis=computed(()=>s.p.value.documentAnalysis),candidates=computed(()=>analysis.value?.people.filter((p:any)=>p.scope==='depicted')||[]),otherPeople=computed(()=>analysis.value?.people.filter((p:any)=>p.scope!=='depicted'&&p.name.includes(query.value))||[])
const source=computed(()=>{const rows=s.p.value.sources.filter((v:any)=>v.documentId===doc.value?.id&&v.page===Number(page.value));return rows.find((v:any)=>v.method==='ocr')||rows[0]}),pageInfo=computed(()=>doc.value?.pages.find((v:any)=>v.page===Number(page.value)))
const titles=computed(()=>Array.from(new Set(docs.value.flatMap((d:any)=>d.pages.slice(0,2).flatMap((p:any)=>[...(p.text||'').matchAll(/《([^《》]{1,60})》/g)].map((m:any)=>m[1]))))))
watch(()=>s.p.value.id,()=>{checked.value=[];selected.value='';target.value=s.p.value.targetArtwork||s.p.value.artworkName||'';error.value='';notice.value='';cancelEdit()}, {immediate:true})
watch(()=>docs.value.map((d:any)=>d.id).join(','),()=>{if(!selected.value&&docs.value.length)selected.value=docs.value[0].id;if(!checked.value.length&&docs.value.length)checked.value=[docs.value[0].id]},{immediate:true})
watch(()=>analysis.value?.id,()=>{personIds.value=analysis.value?.lastAdoption?.characterIds||candidates.value.map((c:any)=>c.id);summaryKinds.value=analysis.value?.lastAdoption?.summaryKinds||['background','relationships','narrative'];updateIds.value=[];cancelEdit()},{immediate:true})
function pagesFor(text:string,count:number){if(!text.trim())return [];const values=new Set<number>();for(const part of text.split(/[,，]/)){const m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error('页码请用 1-3,5 的格式');const a=Number(m[1]),b=Number(m[2]||m[1]);if(a<1||b<a||b>count)throw Error('页码超出文献范围');for(let i=a;i<=b;i++)values.add(i)}return [...values].sort((a,b)=>a-b)}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=e.message||String(e)}finally{busy.value=false}}
async function request(path:string,method:string,body:any){const r=await fetch('/api'+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body instanceof FormData?body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await run(async()=>{await s.saveAll();const form=new FormData();form.append('file',file);await request(`/projects/${s.p.value.id}/documents?version=${s.p.value.version}`,'POST',form);await s.refresh();const d=docs.value[docs.value.length-1];selected.value=d.id;checked.value=[d.id];page.value=1;notice.value=d.format==='pdf'?(s.generating.value&&s.activeJob.value?.request?.documentId!==d.id?'文件已保存；当前任务结束后请点击本地解析':'已上传；本地解析状态见文献列表及顶部任务栏，不会自动调用LLM'):'已导入原文，可选择文献整理'});input.value=''}
async function start(kind:string,extra:any){if(s.generating.value)return;await run(async()=>{await s.saveAll();await request(`/projects/${s.p.value.id}/tasks`,'POST',{version:s.p.value.version,kind,trigger:'user_button',autoEnable:true,...extra});await s.syncLatest();notice.value='任务已提交'})}
async function organize(){await run(async()=>{if(!target.value.trim())throw Error('请填写目标画作名称');if(inputMode.value==='text'&&textInput.value.text.trim())await importText();if(!checked.value.length)throw Error('请选择至少一份文献');const selections=checked.value.map(id=>{const d=docs.value.find((d:any)=>d.id===id);return {documentId:id,pages:pagesFor(ranges.value[id]||'',d.pageCount)}});await s.saveAll();await request(`/projects/${s.p.value.id}/tasks`,'POST',{version:s.p.value.version,kind:'document_analysis',targetArtwork:target.value.trim(),documents:selections,trigger:'user_button',autoEnable:true});await s.syncLatest();notice.value='已提交统一整理任务；完成后在下方查看摘要、人物候选和作品资料库草稿'})}
async function ocr(){try{const selectedPages=pagesFor(ocrRanges.value[doc.value.id]||'',doc.value.pageCount);const pages=selectedPages.length?selectedPages:[Number(page.value)];if(pages.length>20)throw Error('OCR一次最多20页');await start('ocr',{documentId:doc.value.id,pages})}catch(e:any){error.value=e.message}}
async function adopt(){await run(async()=>{await s.saveAll();await request(`/projects/${s.p.value.id}/documents/analysis/adopt`,'POST',{version:s.p.value.version,analysisId:analysis.value.id,summaryKinds:summaryKinds.value,characterIds:personIds.value,updateIds:updateIds.value});await s.refresh();notice.value='已采用所选摘要与画中人物，原页引用保留；人物仍需人工核对确认'})}
function candidateName(c:any){return c.manualProfile?.name||c.creativeNaming?.name||c.name}
function candidateField(c:any,key:string){if(c.manualProfile&&key in c.manualProfile)return c.manualProfile[key];return key==='name'?candidateName(c):key==='identity'&&c.creativeNaming?c.creativeNaming.name:c[key]||''}
function cancelEdit(){editing.value='';editValues.value={};editError.value=''}
function beginEdit(c:any){editing.value=c.id;editValues.value=Object.fromEntries(editFields.map(f=>[f.key,candidateField(c,f.key)]));editError.value=''}
async function saveCandidate(c:any){
 if(!editValues.value.name?.trim()){editError.value='请输入姓名或称谓';return}
 const pid=s.p.value.id,analysisId=analysis.value.id;busy.value=true;editError.value=''
 try{
  await s.saveAll()
  if(pid!==s.p.value.id||analysisId!==analysis.value?.id)throw Error('项目或候选已变化，请重新打开编辑')
  await request(`/projects/${pid}/documents/analysis/people/${c.id}`,'PATCH',{version:s.p.value.version,analysisId,profile:{...editValues.value}})
  if(pid===s.p.value.id){await s.refresh();cancelEdit();notice.value='候选编辑已保存，采用后更新人物档案'}
 }catch(e:any){editError.value=e.message||String(e)}finally{busy.value=false}
}
function existing(c:any){const names=[c.name,c.creativeNaming?.name,...(c.aliases||[]).map((a:any)=>a.name)];return s.p.value.characters.find((v:any)=>names.includes(v.name)||(v.sourceName&&names.includes(v.sourceName)))}
async function previewDoc(id:string){selected.value=id;page.value=1;await nextTick();const el=document.getElementById('document-preview') as HTMLDetailsElement|null;if(el){el.open=true;el.scrollIntoView({block:'start',behavior:'smooth'})}}
async function locate(r:any){selected.value=r.documentId;page.value=r.page;await nextTick();const preview=document.getElementById('document-preview') as HTMLDetailsElement|null;if(preview)preview.open=true;preview?.scrollIntoView({block:'start',behavior:'smooth'})}
watch(()=>s.focus.value,(value:string)=>{if(value.startsWith('document:')){const [,documentId,refPage]=value.split(':');if(docs.value.some((d:any)=>d.id===documentId))locate({documentId,page:Number(refPage)||1})}},{immediate:true})
function referenceLabel(r:any){const d=docs.value.find((d:any)=>d.id===r.documentId);return d?.format==='text'?(d.title||'文本原文')+' · 原文定位':'第'+r.page+'页'}
function qualityLabel(v:string){return ({ready:'已提取文字',review:'需核对文字映射',image_page:'图片为主',blank:'未提取到文字'} as any)[v]||'旧版提取'}
</script>

<template>
<article class="literature-library" data-entity-key="documents">
 <ReviewUnit unit-id="documents:main" label="确认文献资料"/><div class="rail-heading"><div><h2>文献资料</h2><p class="muted">上传文件或直接输入文本，统一整理为摘要、人物候选、逐字依据及作品资料库；点击页面上方“整理资料”即可整理并启用。</p></div></div>
 <p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner" role="status">{{notice}}</p>
 <nav class="literature-input-tabs" aria-label="文献输入模式"><button :class="{selected:inputMode==='file'}" :aria-pressed="inputMode==='file'" @click="inputMode='file'">上传文献文件</button><button :class="{selected:inputMode==='text'}" :aria-pressed="inputMode==='text'" @click="inputMode='text'">输入文本</button></nav>
 <section v-if="inputMode==='file'" class="literature-input-area"><label class="document-upload">选择文献文件<input aria-label="导入文献文件" type="file" accept=".pdf,.txt,.md,.png,.jpg,.jpeg,.webp" :disabled="busy" @change="upload"></label><small>PDF最多100MB、300页；其他资料最多30MB。上传和本地解析不调用模型，扫描页可单独选择OCR。</small></section>
 <section v-else class="literature-input-area"><div class="text-document-heading"><h3>{{textInput.documentId?'编辑文本资料':'输入文献原文'}}</h3><button :disabled="busy" @click="newText">新增文本</button></div><details><summary>标题与出处（可选）</summary><div class="compact-grid"><label>资料标题<input :value="textInput.title" maxlength="200" placeholder="例如：文章标题或手工整理资料" @input="editText('title',($event.target as HTMLInputElement).value)"></label><label>来源与出处<input :value="textInput.citation" maxlength="2000" placeholder="可填写作者、刊物、版本或链接；未知则留空" @input="editText('citation',($event.target as HTMLInputElement).value)"></label></div></details><label>文献原文<textarea :value="textInput.text" rows="12" maxlength="2000000" placeholder="粘贴整段文献或已有资料，保留原文和出处；不用预先分成三段。" :disabled="busy" @input="editText('text',($event.target as HTMLTextAreaElement).value)"/></label><div class="actions"><button :disabled="busy||!textInput.text.trim()" @click="saveText">加入文献资料（不调用模型）</button><button v-if="legacyText" :disabled="busy" @click="copyLegacy">复制已有资料到文本输入</button></div><small>文本与文件使用同一整理流程和结果格式。页面保存会保留未整理的文本草稿；来源未知不等于已核实史实。</small></section>
 <p v-if="!docs.length" class="empty">尚无文献。上传文件或输入文本后，点击页面上方“整理资料”。</p>
 <template v-if="docs.length">
  <div class="document-list"><section v-for="d in docs" :key="d.id" class="document-list-row"><label><input type="checkbox" :value="d.id" v-model="checked">{{d.title}}<small>{{d.inputMode==='text'?'文本输入 · ':''}}{{d.pageCount}}页 | {{d.parseStatus==='queued'?'待本地解析':d.parseStatus==='ready'?'本地解析完成':'已导入'}}</small></label><input v-model="ranges[d.id]" :aria-label="d.title+' 整理页码'" placeholder="全部页；或1-3,5"><button @click="previewDoc(d.id)">{{d.format==='text'?'预览原文':'预览原页'}}</button><button v-if="d.inputMode==='text'" :disabled="busy" @click="editDocument(d)">编辑文本</button><button v-if="d.format==='pdf'" :disabled="busy||s.generating.value" @click="start('document_parse',{documentId:d.id})">重新本地解析</button></section></div>
  <details id="document-preview" :open="false" v-if="doc"><summary>{{doc.title}} 第{{page}}页</summary><div class="actions"><select v-model="selected" @change="page=1" aria-label="预览文献"><option v-for="d in docs" :value="d.id">{{d.title}}</option></select><label>页码<input type="number" min="1" :max="doc.pageCount" v-model.number="page"></label><span class="status-pill">{{source?.method==='ocr'?(source.confirmed?'OCR文字 | 已采用':'OCR文字 | 待校对'):qualityLabel(pageInfo?.quality?.state)}}</span></div><small>{{pageInfo?.quality?.warning||'请对照原页检查文字和阅读顺序，提取成功不代表内容已经核实。'}}</small><div class="document-preview-grid"><img v-if="doc.format!=='text'" :src="`/api/projects/${s.p.value.id}/documents/${doc.id}/pages/${page}`" alt="PDF原页预览"><pre v-else>{{source?.text}}</pre><div><label>本页原文<textarea v-if="source" v-model="source.text" :disabled="s.rootLocked('/sources/@'+source.id)" rows="17"/><p v-else class="empty">未提取到文字，可选择OCR</p></label><template v-if="doc.format!=='text'"><label>OCR页码（最多20页）<input v-model="ocrRanges[doc.id]" placeholder="留空为当前页；或1-3,5"></label><button :disabled="busy||s.generating.value" @click="ocr"><AppIcon name="ai" :size="14"/>OCR所选页</button></template><small>不自动OCR。结果待校对；相关原文改变时保留旧依据，并提醒实际受影响的内容。</small></div></div></details>
 </template>
 <details><summary>高级：选择部分文献重新整理</summary><div class="document-analysis-start"><label>目标画作名称<input v-model="target" list="document-artwork-titles" placeholder="填写本次要分析的画作名称"><datalist id="document-artwork-titles"><option v-for="title in titles" :value="String(title)"/></datalist></label><button class="primary" :disabled="busy||!!editing||s.generating.value||(!checked.length&&!(inputMode==='text'&&textInput.text.trim()))||!s.p.value.image" @click="organize"><AppIcon name="ai" :size="14"/>重新整理所选资料</button><small>统一整理勾选的文件与文本；文本模式会先保存当前原文。只在点击后调用模型，生成同一种摘要、人物候选和结构化草稿，不自动采用或确认。</small></div></details>
 <details v-if="legacyText" class="legacy-material-inputs"><summary>当前已采用的制作摘要／原有资料</summary><p class="muted">保留原有文字和来源关联。可复制到文本模式重新整理；文件与文本的新结果均在下方统一展示。</p><div class="document-summary-grid"><section v-for="(label,kind) in labels"><h4>{{label}}</h4><p class="pre">{{s.p.value.materialInputs[kind]||'未提供'}}</p></section></div><button :disabled="busy" @click="copyLegacy">复制已有资料到文本输入</button></details>
 <section v-if="analysis" class="document-analysis-result"><div class="rail-heading"><h3>资料整理结果</h3><span class="status-pill">{{analysis.status==='adopted'?'已采用过':'待查看采用'}}</span></div><small>已处理{{analysis.selectedPages?.length}}个页面，{{analysis.coverage?.length}}批；本次模型请求{{analysis.modelCalls}}次。摘要不是一级史料，依据引用文献原文。</small>
  <fieldset :disabled="s.rootLocked('/documentAnalysis')||busy"><div class="document-summary-grid"><section v-for="(label,kind) in labels" :key="kind"><label><input type="checkbox" :value="kind" v-model="summaryKinds">采用{{label}}</label><div v-for="para in analysis.summaries[kind]" class="summary-paragraph"><textarea v-model="para.text" rows="5"/><details><summary>原文依据（{{para.references.length}}）</summary><div v-for="r in para.references"><button @click="locate(r)">{{referenceLabel(r)}}</button><q>{{r.quote}}</q></div></details></div><small v-if="!analysis.summaries[kind].length">文献未提供可整理内容，采用后该段留空。</small></section></div>
  <details v-if="analysis.validationWarnings?.length"><summary>待复核（{{analysis.validationWarnings.length}}）</summary><p v-for="w in analysis.validationWarnings"><template v-if="typeof w==='string'">{{w}}</template><template v-else><b>{{w.item}}</b><small>{{w.reason}} | {{w.action}}</small></template></p></details><h3>人物候选（{{candidates.length}}）</h3><small>仅有明确本画描绘依据者进入候选。页面整理资料会匹配画中对应并启用有效结果；此处保留候选及原文，供随时调整。</small><div class="document-person-candidates"><section v-for="c in candidates" :key="c.id"><div class="candidate-heading"><label><input type="checkbox" :value="c.id" v-model="personIds"><b>{{candidateName(c)}}</b></label><button type="button" class="candidate-edit" :aria-label="'编辑人物候选：'+candidateName(c)" :disabled="!!editing" @click="beginEdit(c)"><AppIcon name="edit" :size="14"/>编辑</button></div><form v-if="editing===c.id" class="candidate-editor" @submit.prevent="saveCandidate(c)"><label v-for="field in editFields.slice(0,3)" :key="field.key">{{field.label}}<input v-if="field.rows===1" v-model="editValues[field.key]" :maxlength="field.max" :required="field.key==='name'" :aria-label="'候选'+field.label"><textarea v-else v-model="editValues[field.key]" :maxlength="field.max" :rows="field.rows" :aria-label="'候选'+field.label"/></label><details><summary>经历与关系</summary><label v-for="field in editFields.slice(3)" :key="field.key">{{field.label}}<textarea v-model="editValues[field.key]" :maxlength="field.max" :rows="field.rows" :aria-label="'候选'+field.label"/></label></details><p v-if="editError" class="candidate-edit-error" role="alert">{{editError}}</p><small>仅保存候选，采用后更新人物档案。</small><div class="actions"><button type="submit" class="primary">保存编辑</button><button type="button" @click="cancelEdit">取消编辑</button></div></form><template v-else><small v-if="c.manualProfile">已手动编辑</small><small v-if="c.creativeNaming">创作称谓 | 原文称谓：{{c.name}}；依据中的推测性质保留。</small><small v-else>{{c.namingNote}}</small><p>{{candidateField(c,'summary')||'未提供具体身份／经历'}}</p><small>{{candidateField(c,'identity')}}</small><template v-if="existing(c)"><p>现有：{{existing(c).summary||existing(c).identity||'未提供'}}</p><label><input type="checkbox" :value="existing(c).id" v-model="updateIds">采用此更新并保留已有角色ID</label><small>不勾选则保留已有资料。采用后自动保存；其他可用内容继续保留。</small></template></template><details><summary>查看原文与判断依据</summary><p v-for="a in c.aliasQuestions">待核对称呼：{{a.name}} | {{a.reason}}</p><div v-for="r in c.references"><button @click="locate(r)">{{referenceLabel(r)}}</button><q>{{r.quote}}</q></div><template v-if="c.identityOptions?.length"><p v-for="option in c.identityOptions"><b>{{option.label}}</b> | {{({certain:'明确记载',likely:'文献较明确判断',possible:'不确定解释',rejected:'原文否定'} as any)[option.assessment]||option.assessment}}<template v-for="r in option.references"><button @click="locate(r)">{{referenceLabel(r)}}</button><q>{{r.quote}}</q></template></p></template></details></section></div>
  <details class="document-other-people"><summary>其他人物提及（{{analysis.people.length-candidates.length}}）</summary><input v-model="query" placeholder="按姓名查找文献提及"><section v-for="c in otherPeople" :key="c.id"><b>{{c.name}}</b><small>{{c.contextRoles.map((r:string)=>roles[r]||r).join(' | ')}} | {{c.scope==='unknown'?'范围未定':'非本画人物'}}</small><p>{{c.summary}}</p><small v-for="a in c.aliasQuestions">待核对称呼：{{a.name}} | {{a.reason}}</small><div v-for="r in c.references"><button @click="locate(r)">{{referenceLabel(r)}}</button><q>{{r.quote}}</q></div></section></details>
  <details><summary>查看解释、推测与转引</summary><section v-for="c in analysis.claims.filter((c:any)=>['interpretation','uncertain'].includes(c.assertion)||c.indirectSource)"><p>{{c.text}}</p><small>{{c.assertion==='uncertain'?'未确定观点':c.assertion==='interpretation'?'论文解释':'资料转述'}}{{c.indirectSource?' | 经论文转引：'+c.indirectSource+'（未独立核对原书）':''}}</small><div v-for="r in c.references"><button @click="locate(r)">{{referenceLabel(r)}}</button><q>{{r.quote}}</q></div></section></details>
  <details><summary>高级：单独采用部分结果</summary><button class="primary" :disabled="busy||!!editing||s.rootLocked('/documentAnalysis')||(!summaryKinds.length&&!personIds.length)" @click="adopt">采用所选摘要与人物</button><small>会替换勾选的三段输入，并将所引页面标为已人工采用；不表示独立验证史实。请核对编辑后摘要的引用是否仍适用。</small></details></fieldset>
 </section>
</article>
</template>

